  (* [comment removed for export] *)
  Definition athread_range (a : Z) : Prop :=
    (a_thr s <= a < a_thr s + OT_UNWINDING + 1) \/ (a_ctx s + 8 <= a < a_ctx s + 12) \/ (a_ctx s + 152 <= a < a_ctx s + 160).
